const path = require('path');
const fs = require('fs');

const ROOT = path.join(__dirname, 'templates');

function readTemplate(name) {
  const p = path.join(ROOT, name);
  return fs.readFileSync(p, 'utf8');
}

module.exports = { readTemplate, ROOT };

